struct PointXYZI
{
  float x{0.0F};
  float y{0.0F};
  float z{0.0F};
  float intensity{0.0F};
  friend bool operator==(const PointXYZI & p1, const PointXYZI & p2) noexcept
  {
    return float_eq<float>(p1.x, p2.x) && float_eq<float>(p1.y, p2.y) &&
